        this.dropStableTimer = 0;
        this.screenTimeout = null;
        this.warningCooldown = 0;
        this.chargePadCooldown = 0;
        this.droneLaserCooldown = 0;
        this.cargoLaserCooldown = 0;
        this.failureReason = "";

