"const { chromium } = require('playwright');

(async () => {
    const browser = await chromium.launch({ channel: 'chrome', headless: true });
    const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
    await page.goto('http://localhost:8000', { waitUntil: 'domcontentloaded' });
    await page.waitForTimeout(300);

    // 1. Open Map from title
    await page.click('#title-map-btn');
    await page.waitForTimeout(300);
    const mapVisible = await page.evaluate(() => {
        const screen = document.getElementById('screen-map');
        return screen && !screen.classList.contains('hidden') && window.game.state === 'MAP';
    });
    console.log('Map screen opened successfully:', mapVisible);

    // 2. Open Codex from Map
    await page.click('#map-codex-btn');
    await page.waitForTimeout(200);
    const codexVisible = await page.evaluate(() => {
        const modal = document.getElementById('modal-codex');
        return modal && !modal.classList.contains('hidden');
    });
    console.log('Codex modal opened successfully:', codexVisible);

    // 3. Close Codex
    await page.click('#ack-codex-btn');
    await page.waitForTimeout(200);
    const codexClosed = await page.evaluate(() => {
        const modal = document.getElementById('modal-codex');
        return modal && modal.classList.contains('hidden');
    });
    console.log('Codex modal closed successfully:', codexClosed);

    // 4. Click Sector 1 and Launch
    await page.click('#map-launch-btn');
    await page.waitForTimeout(200);
    const briefingOpened = await page.evaluate(() => {
        const brief = document.getElementById('screen-briefing');
        return brief && !brief.classList.contains('hidden') && window.game.state === 'BRIEFING';
    });
    console.log('Briefing opened from sector map:', briefingOpened);

    // 5. Return to map
